  const compact=n=>{if(!C.number(n))return t('확인 불가','Unavailable');const f=x=>new Intl.NumberFormat(locale(),{maximumFractionDigits:x>=100?0:1}).format(x);if(lang==='en'){const u=[[1e12,'T'],[1e9,'B'],[1e6,'M'],[1e3,'K']].find(([v])=>n>=v);return u?f(n/u[0])+u[1]:exact(n);}return n>=1e8?f(n/1e8)+'억':n>=1e4?f(n/1e4)+'만':exact(n);};
  function date(v,full=false){if(!v)return t('확인 불가','Unknown');const x=new Date(v.length===10?v+'T00:00:00Z':v);if(!Number.isFinite(+x))return t('확인 불가','Unknown');try{return new Intl.DateTimeFormat(locale(),full?{timeZone:S.timezone || 'UTC',year:'numeric',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}:{timeZone:'UTC',month:'short',day:'numeric',year:'numeric'}).format(x);}catch{return x.toISOString();}}
  const age=v=>{if(!v || !Number.isFinite(Date.parse(v)))return t('경과 시간 확인 불가','Age unavailable');const h=Math.max(0,Math.floor((Date.now()-Date.parse(v))/3600000));return h<1?t('1시간 미만 경과','Less than 1 hour old'):t(exact(h)+'시간 경과',exact(h)+(h===1?' hour old':' hours old'));};
