  function issuesHTML(d){const codes=issueCodes(d);if(!codes.length)return '';const known=codes.filter(k=>ISSUES[k]),other=codes.length-known.length,rec=S.datasets.find(x=>recovered(x)&&x.id!==d.id);return `<h3>${recovered(d)?t('Aside 복구 요약 안내','About recovered Aside summaries'):t('집계 시 참고할 점 '+exact(codes.length)+'개','Counting notes: '+exact(codes.length))}</h3>${recovered(d)?`<p>${t('Aside 세션에서 턴 단위로 복구한 요약이에요.','Summaries recovered turn by turn from Aside sessions.')}</p>`:''}<ul>${known.map(k=>`<li>${ISSUES[k]()}${k==='aside_session_files_missing'&&rec?` <button class="text-button" data-recovered="${esc(rec.id)}">${t('복구 요약 보기','Open recovered summaries')}</button>`:''}</li>`).join('')}${other?`<li>${t('설명이 아직 없는 주의 항목이 '+exact(other)+'개 있어요. 상세 진단은 읽기 전용 CLI에서 확인할 수 있어요.',exact(other)+' more notes have no description yet. Read-only CLI diagnostics list the underlying codes.')}</li>`:''}</ul>`;}
